                .filter(|o| o.tapped && !locked_ids.contains(&o.id))
                .map(|o| o.id)
                .collect();

            for id in to_untap {
                state.get_object_mut(id).expect("object must exist for untap").tapped = false;
                state.events.push(GameEvent::Untapped { object: id });
